import os
from typing import Any, Dict, List, Optional

import boto3


class BedrockPlatformClient:
    def __init__(
        self,
        *,
        region_name: Optional[str] = None,
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
        aws_session_token: Optional[str] = None,
    ) -> None:
        self.client = boto3.client(
            "bedrock-runtime",
            region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
            aws_access_key_id=aws_access_key_id or os.getenv("AWS_ACCESS_KEY_ID"),
            aws_secret_access_key=aws_secret_access_key or os.getenv("AWS_SECRET_ACCESS_KEY"),
            aws_session_token=aws_session_token or os.getenv("AWS_SESSION_TOKEN"),
        )

    def invoke_via_inference_profile(
        self,
        *,
        inference_profile_arn: str,
        prompt: str,
        system: Optional[str] = None,
        temperature: float = 0.7,
        max_tokens: int = 512,
        top_p: float = 0.9,
        stop_sequences: Optional[List[str]] = None,
    ) -> Dict[str, Any]:
        messages: List[Dict[str, Any]] = [
            {
                "role": "user",
                "content": [{"text": prompt}],
            }
        ]

        payload: Dict[str, Any] = {
            "anthropic_version": "bedrock-2023-05-31",
            "max_tokens": max_tokens,
            "temperature": temperature,
            "top_p": top_p,
            "messages": messages,
        }

        if system:
            payload["system"] = system
        if stop_sequences:
            payload["stop_sequences"] = stop_sequences

        response = self.client.invoke_model(
            modelId=inference_profile_arn,
            contentType="application/json",
            accept="application/json",
            body=json_bytes(payload),
        )

        body = parse_bedrock_body(response["body"].read())
        return {
            "provider": "aws_bedrock",
            "model_family": "anthropic.claude-3-5-sonnet",
            "inference_profile_arn": inference_profile_arn,
            "id": body.get("id"),
            "role": body.get("role"),
            "text": extract_text(body),
            "stop_reason": body.get("stop_reason"),
            "usage": body.get("usage", {}),
            "raw": body,
        }


def json_bytes(obj: Dict[str, Any]) -> bytes:
    import json

    return json.dumps(obj).encode("utf-8")


def parse_bedrock_body(data: bytes) -> Dict[str, Any]:
    import json

    return json.loads(data.decode("utf-8"))


def extract_text(body: Dict[str, Any]) -> str:
    parts = body.get("content", [])
    texts: List[str] = []
    for item in parts:
        if isinstance(item, dict) and item.get("type") == "text":
            texts.append(item.get("text", ""))
    return "".join(texts)
